WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT p.pedido_id, p.cliente, p.site, p.status, p.segmento, p.segmento_origem, COALESCE(e.nome, 'não informado') AS executivo, p.executivo_id, p.commit_codigo, p.produtos, p.categorias, p.fonte, p.preco, p.logo_url, CAST(p.catalogo AS TEXT) AS catalogo, CAST(p.resumo AS TEXT) AS resumo, p.portal_id, p.portal_url, p.banners_situacao, p.banner_cor, p.observacoes, p.erro, p.erro_codigo, p.motivo_catalogo, p.modelo_ia, p.custo_ia_usd, p.tokens_ia, p.produtos_similares, p.simulado, p.criado_em, p.extracao_fim, p.curadoria_fim, p.criacao_inicio, p.concluido_em, p.falhou_em, p.execucao_acao, p.execucao_desde, p.anexo_nome, p.nomes_lidos_na_imagem, p.motivo_catalogo AS motivo_precisa_catalogo, (p.execucao_atual IS NOT NULL) AS em_execucao FROM pedidos p JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) LEFT JOIN executivos e ON e.id = p.executivo_id WHERE p.pedido_id = :pedido_id
